package org.springframework.samples.petclinic.rest.function.owner;

import java.util.concurrent.atomic.AtomicLong;

import net.officefloor.plugin.variable.Val;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.samples.petclinic.model.MembershipLevel;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Emits, on the dedicated {@code AUDIT} logger, the side-effects of a successfully
 * created owner. Two things are logged:
 * <ol>
 * <li>a human-readable audit line carrying the owner id, memberId,
 * registrationDate and membershipLevel; and</li>
 * <li>an immutable structured {@link OwnerCreatedEvent} rendered as JSON
 * ({@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}),
 * whose {@code seq} increases monotonically across all creates.</li>
 * </ol>
 * Runs after {@link SaveOwner} so the generated id is available.
 */
public class AuditOwnerCreated {

    private static final Logger audit = LoggerFactory.getLogger("AUDIT");

    /** Monotonically increasing sequence shared across all owner creates. */
    private static final AtomicLong SEQ = new AtomicLong();

    public void service(@Val Owner owner) {
        audit.info(
                "Owner created id={} memberId={} registrationDate={} membershipLevel={}",
                owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
                MembershipLevel.of(owner));

        audit.info(OwnerCreatedEvent.of(SEQ.incrementAndGet(), owner).toJson());
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.MembershipLevel;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Immutable structured audit event emitted (as JSON) when an owner is created.
 *
 * <p>Besides the human-readable audit line, {@link AuditOwnerCreated} emits one of
 * these per successful create as
 * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}.
 *
 * <p>The event carries the owner's <em>current primary identifier</em>, the unified
 * {@code memberId}; the value is sourced in a single place
 * ({@link #primaryIdentifier(Owner)}).
 *
 * <p>A record: once constructed the event cannot be mutated.
 */
public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId, int membershipLevel) {

    /** The {@code event} discriminator carried by every owner-created event. */
    public static final String EVENT = "OWNER_CREATED";

    /**
     * Builds the event for a freshly created owner, reading the current primary
     * identifier and derived membership level from it.
     */
    public static OwnerCreatedEvent of(long seq, Owner owner) {
        return new OwnerCreatedEvent(seq, owner.getId(), primaryIdentifier(owner),
                MembershipLevel.of(owner));
    }

    /** The owner's current primary identifier, the unified {@code memberId}. */
    private static String primaryIdentifier(Owner owner) {
        return owner.getMemberId();
    }

    /**
     * Renders the event as a compact JSON object with a stable key order:
     * {@code {"seq":..,"ownerId":..,"memberId":..,"membershipLevel":..,"event":"OWNER_CREATED"}}.
     */
    public String toJson() {
        StringBuilder sb = new StringBuilder(96);
        sb.append('{');
        sb.append("\"seq\":").append(seq);
        sb.append(",\"ownerId\":").append(ownerId);
        sb.append(",\"memberId\":").append(jsonString(memberId));
        sb.append(",\"membershipLevel\":").append(membershipLevel);
        sb.append(",\"event\":").append(jsonString(EVENT));
        sb.append('}');
        return sb.toString();
    }

    /** JSON-encodes a string value, or the literal {@code null} when absent. */
    private static String jsonString(String value) {
        if (value == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder(value.length() + 2);
        sb.append('"');
        for (int i = 0; i < value.length(); i++) {
            char c = value.charAt(i);
            switch (c) {
                case '"' -> sb.append("\\\"");
                case '\\' -> sb.append("\\\\");
                case '\n' -> sb.append("\\n");
                case '\r' -> sb.append("\\r");
                case '\t' -> sb.append("\\t");
                default -> {
                    if (c < 0x20) {
                        sb.append(String.format("\\u%04x", (int) c));
                    } else {
                        sb.append(c);
                    }
                }
            }
        }
        sb.append('"');
        return sb.toString();
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.HashSet;
import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.MemberId;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Assigns the owner's unified {@code memberId}, formatted
 * {@code <REGION><FY><HASH8><CHK>} (see {@link MemberId}). When the computed id collides
 * with an existing owner's {@code memberId}, {@code -<n>} is appended with the smallest
 * {@code n} of 2 or more that makes it unique. Runs after {@link BuildOwner} (so the
 * telephone is normalized and the registrationDate is set) and before {@link SaveOwner}.
 */
public class AssignMemberId {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String base = MemberId.of(owner);
        owner.setMemberId(deduplicate(base, existingMemberIds(ownerRepository)));
    }

    private static Set<String> existingMemberIds(OwnerRepository ownerRepository) {
        Set<String> ids = new HashSet<>();
        for (Owner existing : ownerRepository.findAll()) {
            String id = existing.getMemberId();
            if (id != null) {
                ids.add(id);
            }
        }
        return ids;
    }

    /** Returns {@code base}, or {@code base-<n>} with the smallest {@code n >= 2} not in {@code taken}. */
    private static String deduplicate(String base, Set<String> taken) {
        if (!taken.contains(base)) {
            return base;
        }
        for (int n = 2; ; n++) {
            String candidate = base + "-" + n;
            if (!taken.contains(candidate)) {
                return candidate;
            }
        }
    }
}

